CustomField.formula:
IF( (TODAY() - DATEVALUE(CreatedDate)) < 7, 
  "00 This Week",
  IF( (TODAY() - DATEVALUE(CreatedDate)) < 14, 
    "01 Last Week",
    /* Logic for 2+ Weeks Ago */
    IF( FLOOR((TODAY() - DATEVALUE(CreatedDate)) / 7) < 10, "0", "") & 
    TEXT(FLOOR((TODAY() - DATEVALUE(CreatedDate)) / 7)) & " Weeks Ago"
  )
)
